'use client';
import {type ReactNode} from 'react';
import './block-data-table24.css';
export interface GroupedTransaction {id:string;reference:string;amount:number;currency:string;tax?:number;client:string;description:string;href?:string}
export interface TransactionGroup {id:string;label:string;transactions:GroupedTransaction[]}
export interface BlockDataTable24Props {groups:TransactionGroup[];title?:string;description?:ReactNode;formatAmount?:(amount:number,currency:string)=>string;onTransactionSelect?:(transaction:GroupedTransaction)=>void;className?:string}
const money=(n:number,currency:string)=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format(n);
export function BlockDataTable24({groups,title='Data table with hidden headings',description='A data table with hidden headings and grouped rows perfect for separating different tables rows within the table',formatAmount=money,onTransactionSelect,className=''}:BlockDataTable24Props){return <section className={`block-data-table24 ${className}`} data-capture-root><div className="dt24-inner"><h2>{title}</h2><p className="dt24-description">{description}</p><div className="dt24-scroll"><table><colgroup><col style={{width:'16.3%'}}/><col style={{width:'29%'}}/><col style={{width:'23.4%'}}/><col style={{width:'31.3%'}}/></colgroup><thead className="dt24-sr"><tr><th>Invoice</th><th>Amount</th><th>Client</th><th>Description</th></tr></thead>{groups.map(group=><tbody key={group.id} data-group-id={group.id}><tr className="dt24-group"><th scope="rowgroup" colSpan={4}>{group.label}</th></tr>{group.transactions.map(transaction=><tr key={transaction.id} data-transaction-id={transaction.id}><td><a href={transaction.href||'#'} onClick={e=>{if(onTransactionSelect){e.preventDefault();onTransactionSelect(transaction)}}}>{transaction.reference}</a></td><td><span className="dt24-amount">{formatAmount(transaction.amount,transaction.currency)} {transaction.currency}</span>{transaction.tax!==undefined&&<span className="dt24-tax">+ {formatAmount(transaction.tax,transaction.currency)} tax</span>}</td><td>{transaction.client}</td><td>{transaction.description}</td></tr>)}</tbody>)}</table>{!groups.some(group=>group.transactions.length>0)&&<p className="dt24-empty">No transactions.</p>}</div></div></section>}
export default BlockDataTable24;
